{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2136-03-23 01:30:00",
      "speaker": "Doctor",
      "text": "Hello, Mr. Johnson. I'm Dr. Lee. I understand your feeding tube cracked earlier today. Can you tell me how you're feeling?"
    },
    {
      "turn_number": 2,
      "time": "2136-03-23 01:30:15",
      "speaker": "Patient",
      "text": "I can't speak, but I'm okay. Just didn't get my feeds."
    },
    {
      "turn_number": 3,
      "time": "2136-03-23 01:30:30",
      "speaker": "Doctor",
      "text": "I see. You're nodding—thank you. We’ll take care of the tube. You’re not in pain or feverish?"
    },
    {
      "turn_number": 4,
      "time": "2136-03-23 01:30:45",
      "speaker": "Patient",
      "text": "No fever. Just a little tired."
    },
    {
      "turn_number": 5,
      "time": "2136-03-23 01:31:00",
      "speaker": "Doctor",
      "text": "Your vitals look stable. We did some blood work and your white blood cell count is a bit high. Any burning when you urinate?"
    },
    {
      "turn_number": 6,
      "time": "2136-03-23 01:31:15",
      "speaker": "Patient",
      "text": "Can't tell. I have a catheter."
    },
    {
      "turn_number": 7,
      "time": "2136-03-23 01:31:30",
      "speaker": "Doctor",
      "text": "Right. The urine test shows signs of infection—Proteus bacteria. But since you’re not sick, we won’t use antibiotics now."
    },
    {
      "turn_number": 8,
      "time": "2136-03-23 01:31:45",
      "speaker": "Patient",
      "text": "Is that dangerous?"
    },
    {
      "turn_number": 9,
      "time": "2136-03-23 01:32:00",
      "speaker": "Doctor",
      "text": "Not right now. With long-term catheters, bacteria often grow but don’t cause illness. We’ll change your catheter to reduce risk."
    },
    {
      "turn_number": 10,
      "time": "2136-03-23 01:32:15",
      "speaker": "Patient",
      "text": "Okay. What about the feeding tube?"
    },
    {
      "turn_number": 11,
      "time": "2136-03-23 01:32:30",
      "speaker": "Doctor",
      "text": "We’ll replace it tomorrow morning. It’s a quick procedure. After that, you can resume your feeds."
    },
    {
      "turn_number": 12,
      "time": "2136-03-23 01:32:45",
      "speaker": "Patient",
      "text": "Will it hurt?"
    },
    {
      "turn_number": 13,
      "time": "2136-03-23 01:33:00",
      "speaker": "Doctor",
      "text": "You’ll get numbing gel, so it should be comfortable. A specialist will do it with X-ray guidance."
    },
    {
      "turn_number": 14,
      "time": "2136-03-23 01:33:15",
      "speaker": "Patient",
      "text": "Good. My legs ache a bit."
    },
    {
      "turn_number": 15,
      "time": "2136-03-23 01:33:30",
      "speaker": "Doctor",
      "text": "I saw that. Likely neuropathy from diabetes. We’ll keep your pain meds—gabapentin, morphine, and the fentanyl patch."
    },
    {
      "turn_number": 16,
      "time": "2136-03-23 01:33:45",
      "speaker": "Patient",
      "text": "Thank you. I’ve had infections before."
    },
    {
      "turn_number": 17,
      "time": "2136-03-23 01:34:00",
      "speaker": "Doctor",
      "text": "Yes, your history shows past UTIs and sepsis. That’s why we’re cautious. But today, you’re stable—no fever, normal oxygen."
    },
    {
      "turn_number": 18,
      "time": "2136-03-23 01:34:15",
      "speaker": "Patient",
      "text": "I’m DNR. Still okay?"
    },
    {
      "turn_number": 19,
      "time": "2136-03-23 01:34:30",
      "speaker": "Doctor",
      "text": "Yes, your DNR/DNI status is documented and respected. We’ll focus on comfort and treating only what’s necessary."
    },
    {
      "turn_number": 20,
      "time": "2136-03-23 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. Your white count was high last night but is already coming down. That’s a good sign."
    },
    {
      "turn_number": 21,
      "time": "2136-03-23 08:15:15",
      "speaker": "Patient",
      "text": "So no antibiotics?"
    },
    {
      "turn_number": 22,
      "time": "2136-03-23 08:15:30",
      "speaker": "Doctor",
      "text": "Correct. Starting them without symptoms could lead to resistance. We changed your catheter this morning to reduce future risks."
    },
    {
      "turn_number": 23,
      "time": "2136-03-23 08:15:45",
      "speaker": "Patient",
      "text": "Smart. What about the chest X-ray?"
    },
    {
      "turn_number": 24,
      "time": "2136-03-23 08:16:00",
      "speaker": "Doctor",
      "text": "It shows some atelectasis—collapsed lung areas—common in people with trachs. But no pneumonia. We’ll keep encouraging breathing treatments."
    },
    {
      "turn_number": 25,
      "time": "2136-03-23 08:16:15",
      "speaker": "Patient",
      "text": "I use the nebulizer when needed."
    },
    {
      "turn_number": 26,
      "time": "2136-03-23 08:16:30",
      "speaker": "Doctor",
      "text": "Yes, ipratropium-albuterol as needed. Your lungs sound coarse but clear of infection."
    },
    {
      "turn_number": 27,
      "time": "2136-03-23 11:45:00",
      "speaker": "Doctor",
      "text": "We’re about to replace your feeding tube. Any questions before we go?"
    },
    {
      "turn_number": 28,
      "time": "2136-03-23 11:45:15",
      "speaker": "Patient",
      "text": "How long will it take?"
    },
    {
      "turn_number": 29,
      "time": "2136-03-23 11:45:30",
      "speaker": "Doctor",
      "text": "About 30 minutes. You’ll be awake but comfortable. We’ll use a guidewire to place the new tube."
    },
    {
      "turn_number": 30,
      "time": "2136-03-23 11:45:45",
      "speaker": "Patient",
      "text": "Okay. I trust you."
    },
    {
      "turn_number": 31,
      "time": "2136-03-23 12:30:00",
      "speaker": "Doctor",
      "text": "All done. The new tube is in place. We flushed it and it’s working. You can restart feeds in an hour."
    },
    {
      "turn_number": 32,
      "time": "2136-03-23 12:30:15",
      "speaker": "Patient",
      "text": "Great. I was hungry."
    },
    {
      "turn_number": 33,
      "time": "2136-03-23 14:00:00",
      "speaker": "Doctor",
      "text": "Your labs this morning show your white count dropped to 10.2. That means your body is handling things well."
    },
    {
      "turn_number": 34,
      "time": "2136-03-23 14:00:15",
      "speaker": "Patient",
      "text": "So I can go back soon?"
    },
    {
      "turn_number": 35,
      "time": "2136-03-23 14:00:30",
      "speaker": "Doctor",
      "text": "Likely tomorrow. We’ll watch you overnight. Your INR was a bit low but is improving with warfarin."
    },
    {
      "turn_number": 36,
      "time": "2136-03-23 14:00:45",
      "speaker": "Patient",
      "text": "I take 4 mg daily."
    },
    {
      "turn_number": 37,
      "time": "2136-03-23 14:01:00",
      "speaker": "Doctor",
      "text": "We kept that dose. It’s now 2.3—perfect. Your thyroid and diabetes are stable too. TSH and glucose are fine."
    },
    {
      "turn_number": 38,
      "time": "2136-03-24 09:00:00",
      "speaker": "Doctor",
      "text": "Good news. You’re ready to go back to rehab today. Your tube is working, infection signs are down, and you’re stable."
    },
    {
      "turn_number": 39,
      "time": "2136-03-24 09:00:15",
      "speaker": "Patient",
      "text": "No new meds?"
    },
    {
      "turn_number": 40,
      "time": "2136-03-24 09:00:30",
      "speaker": "Doctor",
      "text": "No changes. Same doses. Just keep turning every two hours for your back sore and use the pressure-relief cushion when seated."
    },
    {
      "turn_number": 41,
      "time": "2136-03-24 09:00:45",
      "speaker": "Patient",
      "text": "I will. Thank you for explaining everything."
    },
    {
      "turn_number": 42,
      "time": "2136-03-24 09:01:00",
      "speaker": "Doctor",
      "text": "You’re welcome. If the tube leaks or you feel unwell, let the nursing home know right away."
    },
    {
      "turn_number": 43,
      "time": "2136-03-24 09:01:15",
      "speaker": "Patient",
      "text": "I will. See you hopefully not soon!"
    },
    {
      "turn_number": 44,
      "time": "2136-03-24 09:01:30",
      "speaker": "Doctor",
      "text": "Take care, Mr. Johnson. Stay well."
    }
  ],
  "summary": {
    "admission_start": "2136-03-23 01:24:00",
    "admission_end": "2136-03-24 15:36:00",
    "summary_paragraph": "A 68-year-old male with a history of stroke, tracheostomy, G-tube, atrial fibrillation on anticoagulation, diabetes, and recurrent infections was admitted due to a cracked PEG tube that prevented tube feeding. He had no acute symptoms but presented with leukocytosis and a positive urine culture for Proteus mirabilis. Given his stable condition and lack of infection signs, antibiotics were deferred. The PEG tube was successfully replaced, and his Foley catheter was changed to reduce future infection risk. His white blood cell count improved, and chronic conditions including diabetes, atrial fibrillation, and neuropathic pain were managed. He remained DNR/DNI throughout and was discharged to extended care with no medication changes and wound care instructions for a sacral pressure ulcer.",
    "problems": [
      "Mechanical complication of gastrostomy",
      "Urinary tract infection, site not specified",
      "Diabetes mellitus without mention of complication, type II or unspecified type, not stated as uncontrolled",
      "Atrial fibrillation",
      "Tracheostomy status",
      "Pressure ulcer, lower back",
      "Depressive disorder, not elsewhere classified",
      "Unspecified essential hypertension",
      "Unspecified acquired hypothyroidism",
      "Anemia, unspecified",
      "Peripheral vascular disease, unspecified"
    ]
  }
}
